public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a set to store the visited n-tersections
    Set<Integer> visited = new HashSet<>();

    // Initialize a queue to store the n-tersections to be visited
    Queue<Integer> queue = new LinkedList<>();

    // Add the starting n-tersection to the queue
    queue.add(start[0]);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current n-tersection from the queue
        int current = queue.poll();

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (current == end[0]) {
            return "can be travelled";
        }

        // If the current n-tersection has not been visited, mark it as visited and add its adjacent n-tersections to the queue
        if (!visited.contains(current)) {
            visited.add(current);
            for (int[] path : paths) {
                if (path[0] == current) {
                    queue.add(path[1]);
                }
            }
        }
    }

    // If the queue is empty and the ending n-tersection has not been visited, return "cannot be travelled"
    return "cannot be travelled";
}
